def assembler(LEXIQUE_ANCIEN, QUIZ_ANCIEN):
    """lexique complet rangé par niveau, carte slug → niveau, et banque de quiz (q, c, b, e, p, n)"""
    niveau = dict(NIVEAU_ANCIENS)
    for n, termes in TERMES.items():
        for t in termes: niveau[t[0]] = n
    ordre = [k for k, _, _ in NIVEAUX]
    lex = sorted(list(LEXIQUE_ANCIEN) + [t for termes in TERMES.values() for t in termes], key=lambda e: ordre.index(niveau[e[0]]))
    quiz = [tuple(q) + (NIVEAU_QUIZ_ANCIENS[i],) for i, q in enumerate(QUIZ_ANCIEN)]
    quiz += [(q, c, b, e, None, n) for n, q, c, b, e in QUIZ_PLUS]
    slugs = {e[0] for e in lex}
    manquants = {v for e in lex for v in e[6] if v not in slugs}
    assert not manquants, f'liens « voir aussi » sans terme : {manquants}'
    return lex, niveau, quiz
